test("The front page shows the featured essay and the earlier ones", async ({ browser, baseURL, page, context }) => {
  const j = await Journey.start({ browser, baseURL, page, context }, [], { logs: false });
  try {
    await j.goto("/");
    await expect(j.page).toHaveTitle("Fieldnotes");
    await expect(j.page.getByRole("heading", { name: "Fieldnotes", exact: true, level: 1 })).toBeVisible();
    await expect(j.page.getByRole("heading", { name: "The Jig Is the Work", exact: true, level: 2 })).toBeVisible();
    await expect(j.page.getByRole("region", { name: "Earlier essays", exact: true }).getByRole("article")).toHaveCount(5);
    await j.expectNoText(null, j.text("Notes Toward a Workbench"), undefined);
    await expect(j.page.getByRole("img", { name: j.re("plywood fixture holding a chair leg") })).toBeVisible();
    await expect(j.page.locator("html")).toHaveAttribute("data-accent", "moss");
  } finally {
    await j.close();
  }
});
